class Solution { fun countPalindromePaths(parent:List<Int>,s:String):Long{val mask=IntArray(parent.size);val frequency=HashMap<Int,Int>();var answer=0L;for(node in parent.indices){if(node>0)mask[node]=mask[parent[node]] xor (1 shl (s[node]-'a'));answer+=(frequency[mask[node]]?:0);for(bit in 0 until 26)answer+=(frequency[mask[node] xor (1 shl bit)]?:0);frequency[mask[node]]=(frequency[mask[node]]?:0)+1};return answer} }
